function productionSources(relativeDir = ''): Array<{ path: string; source: string }> {
  const absolute = join(sourceRoot, relativeDir);
  const rows: Array<{ path: string; source: string }> = [];
  for (const entry of readdirSync(absolute, { withFileTypes: true })) {
    const relativePath = relativeDir ? `${relativeDir}/${entry.name}` : entry.name;
    if (entry.isDirectory()) {
      if (!['tasks', 'tests', 'generated'].includes(entry.name)) rows.push(...productionSources(relativePath));
      continue;
    }
    if (entry.isFile() && relativePath.endsWith('.ts')) rows.push({ path: relativePath, source: source(relativePath) });
  }
  return rows;
}

async function waitFor(predicate: () => boolean, message: string): Promise<void> {
  const deadline = Date.now() + 3_000;
  while (Date.now() < deadline) {
    if (predicate()) return;
    await new Promise(resolvePromise => setTimeout(resolvePromise, 10));
  }
  throw new Error(message);
}

function waitForExit(child: ReturnType<typeof spawn>): Promise<number | null> {
  return new Promise((resolvePromise, reject) => {
    child.once('error', reject);
    child.once('close', code => resolvePromise(code));
  });
}

