    ? result?.exitCode ?? 0
    : result?.exitCode && result.exitCode !== 0
      ? result.exitCode
      : run.state === 'timed_out'
        ? 124
        : 1;
  return {
    stdout,
    stdoutDigest: injectedOutcome.value?.stdoutDigest ?? createHash('sha256').update(rawStdout, 'utf8').digest('hex'),
